// =============================================================================
// YunLeFun Design —— 晴空蓝为主，极光点缀
// -----------------------------------------------------------------------------
// 晴空蓝负责主操作、链接和选中状态；极光用于可选的品牌展示。
// 语义色负责状态，前景与背景成组维护，明暗主题共享相同角色。
// 组件以 var(--ylf-*) 引用这些 token（均带兜底值），加载本文件即生效。
// =============================================================================

:root,
.ylf-theme-light {
  // --- brand：晴空蓝 ---------------------------------------------------------
  --ylf-c-brand: #2563eb;
  --ylf-c-brand-hover: #1d4ed8;
  --ylf-c-brand-active: #1e40af;
  --ylf-c-brand-soft: #eff6ff;

  // --- aurora 极光：冷调 dreamy 渐变（蓝 → 鸢尾 → 兰紫，邻近色，不再彩虹） -----
  // 收敛到三色同族，去掉破坏协调的金/绿；签名一条连续的「夜空极光」丝带。
  --ylf-aurora-sky: #5ba3ff;
  --ylf-aurora-iris: #7b61ff;
  --ylf-aurora-pink: #e879c6;
  --ylf-gradient-aurora: linear-gradient(115deg, #5ba3ff 0%, #7b61ff 50%, #e879c6 100%);
  --ylf-gradient-brand: linear-gradient(115deg, #2563eb, #0ea5e9 55%, #0891b2);

  // --- semantic：兼顾实色控件白字与浅色表面文字 -------------------------------
  --ylf-c-success: #065f46;
  --ylf-c-warning: #92400e;
  --ylf-c-danger: #b91c1c;
  --ylf-c-info: #0369a1;

  // --- neutrals 晴空中性色 ----------------------------------------------------
  --ylf-c-bg: #f8fafc;
  --ylf-c-bg-soft: #f1f5f9;
  --ylf-c-bg-mute: #e2e8f0;
  --ylf-c-surface: #ffffff;

  --ylf-c-text: #0f172a;
  --ylf-c-text-2: #475569;
  --ylf-c-text-3: #64748b;
  --ylf-c-text-on-accent: #ffffff;
  --ylf-c-text-on-aurora: #020617;

  --ylf-c-border: #e2e8f0;
  --ylf-c-border-strong: #cbd5e1;
  --ylf-c-overlay: rgba(13, 17, 32, 0.45);

  // --- glass 云玻璃 -----------------------------------------------------------
  --ylf-glass-bg: rgba(255, 255, 255, 0.62);
  --ylf-glass-border: rgba(255, 255, 255, 0.7);
  --ylf-glass-blur: saturate(160%) blur(16px);

  // --- radius 圆角（云是软的） ------------------------------------------------
  --ylf-radius-sm: 10px;
  --ylf-radius: 14px;
  --ylf-radius-lg: 20px;
  --ylf-radius-xl: 28px;
  --ylf-radius-pill: 999px;

  // --- shadow 色染柔影（投影带品牌色而非灰） ----------------------------------
  --ylf-shadow-sm: 0 2px 8px -2px rgba(15, 23, 42, 0.12);
  --ylf-shadow: 0 10px 28px -8px rgba(15, 23, 42, 0.16);
  --ylf-shadow-lg: 0 22px 56px -14px rgba(15, 23, 42, 0.22);
  // 实色主按钮辉光（品牌色）；极光辉光留给 aurora 变体
  --ylf-glow-brand: 0 6px 18px -8px rgba(37, 99, 235, 0.35);
  --ylf-glow-brand-hover: 0 8px 22px -8px rgba(37, 99, 235, 0.4);
  --ylf-glow-aurora: 0 10px 30px -6px rgba(124, 92, 255, 0.5);
  --ylf-glow-aurora-hover: 0 16px 40px -8px rgba(124, 92, 255, 0.6);

  // --- typography -------------------------------------------------------------
  // 圆体做展示字，呼应「云是软的」：拉丁 Baloo 2 + 中文 ZCOOL KuaiLe 站酷快乐体
  // （Google Fonts / OFL，圆润活泼）。Baloo 2 无中文字形，故中文需要补一款圆体 display。
  // 逐字回退 (per-glyph fallback)：
  //   拉丁 / 数字 → Baloo 2
  //   中文        → ZCOOL KuaiLe（需加载，仅 display 角色）
  //               → ui-rounded / 丸ゴシック（系统圆体兜底）
  //               → 苹方 / 雅黑（非圆体系统中文，最终兜底）→ sans-serif
  // 字体加载见 ./fonts.scss 或文档 /guide/typography；正文请用 --ylf-font-body（零 webfont）。
  --ylf-font-display:
    'Baloo 2', 'ZCOOL KuaiLe', ui-rounded, 'Hiragino Maru Gothic ProN', 'Hiragino Maru Gothic Pro', 'PingFang SC',
    'Hiragino Sans GB', 'Microsoft YaHei', '微软雅黑', 'Source Han Sans SC', sans-serif;
  // 品牌字 wordmark（如「云乐坊」）：目前等同 display，独立 token 便于单独调校字重/字距
  --ylf-font-wordmark: var(--ylf-font-display);
  // 产品标题：页面、区块与卡片标题默认使用系统圆润无衬线，不触发 webfont 下载
  // 与 display 分开，避免站酷快乐体、楷体等装饰字体进入密集产品界面。
  --ylf-font-heading:
    ui-rounded, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', '微软雅黑', 'Source Han Sans SC', system-ui,
    sans-serif;
  --ylf-font-body: 'Inter', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', system-ui, sans-serif;

  // --- transition -------------------------------------------------------------
  --ylf-ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);

  // --- 向后兼容别名（旧组件仍在用） -------------------------------------------
  --ylf-c-primary: var(--ylf-c-brand);
  --ylf-c-text-light: var(--ylf-c-text-2);
  --ylf-c-text-lighter: var(--ylf-c-text-3);
  --ylf-c-text-lightest: var(--ylf-c-border-strong);
  --ylf-c-bg-light: var(--ylf-c-bg-soft);
  --ylf-c-bg-lighter: var(--ylf-c-bg-mute);
}

.dark,
.ylf-theme-dark {
  --ylf-c-brand: #60a5fa;
  --ylf-c-brand-hover: #93c5fd;
  --ylf-c-brand-active: #3b82f6;
  --ylf-c-brand-soft: #172554;
  --ylf-gradient-brand: linear-gradient(115deg, #3b82f6, #22d3ee 55%, #06b6d4);

  --ylf-c-success: #34d399;
  --ylf-c-warning: #fbbf24;
  --ylf-c-danger: #fb7185;
  --ylf-c-info: #38bdf8;

  // 深色 = 夜空（不是死黑，是深蓝夜空）
  --ylf-c-bg: #0b1022;
  --ylf-c-bg-soft: #0f1630;
  --ylf-c-bg-mute: #1f2a47;
  --ylf-c-surface: #121a30;

  --ylf-c-text: #e5e7eb;
  --ylf-c-text-2: #cbd5e1;
  --ylf-c-text-3: #94a3b8;
  --ylf-c-text-on-accent: #0f172a;

  --ylf-c-border: #2a3658;
  --ylf-c-border-strong: #3c4c74;
  --ylf-c-overlay: rgba(3, 6, 18, 0.7);

  --ylf-glass-bg: rgba(18, 26, 48, 0.55);
  --ylf-glass-border: rgba(96, 165, 250, 0.18);

  --ylf-shadow-sm: 0 2px 10px -2px rgba(0, 0, 0, 0.5);
  --ylf-shadow: 0 12px 30px -8px rgba(0, 0, 0, 0.55);
  --ylf-shadow-lg: 0 24px 60px -14px rgba(0, 0, 0, 0.6);
  --ylf-glow-brand: 0 6px 18px -8px rgba(96, 165, 250, 0.3);
  --ylf-glow-brand-hover: 0 8px 22px -8px rgba(96, 165, 250, 0.4);
  --ylf-glow-aurora: 0 12px 34px -6px rgba(142, 124, 255, 0.55);
  --ylf-glow-aurora-hover: 0 16px 40px -8px rgba(142, 124, 255, 0.6);
}
